declare(strict_types=1);require_once __DIR__.'/config/sales_step15.php';$error=null;$checks=[];$metrics=[];function s15add(array &$a,string $n,bool $ok,string $d):void{$a[]=['name'=>$n,'ok'=>$ok,'detail'=>$d];}
try{$pdo=business_db();sales_step15_ensure($pdo);sales_step15_backfill($pdo);$ctx=sales_step15_context($pdo);$orgId=(int)$ctx['organization_id'];$scalar=function(string $sql,array $args=[])use($pdo):int{$s=$pdo->prepare($sql);$s->execute($args);return(int)$s->fetchColumn();};$state=$pdo->prepare("SELECT COUNT(*) total_rows,SUM(mapping_status='mapped') mapped_rows,SUM(mapping_status='pending') pending_rows FROM raw_source_records WHERE organization_id=? AND source_dataset IN ('New UMS','Volume Points','First & Second Set','Active UMS Month_Wise','Renewal UMS','Monthely_Income','Royalty_Tracking','Extra Order for Customer')");$state->execute([$orgId]);$legacy=$state->fetch()?:[];$metrics['legacy_total']=(int)($legacy['total_rows']??0);$metrics['legacy_mapped']=(int)($legacy['mapped_rows']??0);$metrics['legacy_pending']=(int)($legacy['pending_rows']??0);$metrics['products']=$scalar("SELECT COUNT(*) FROM products WHERE organization_id=? AND status='active'",[$orgId]);$metrics['sales']=$scalar("SELECT COUNT(*) FROM product_sale_ledger WHERE organization_id=?",[$orgId]);$metrics['customers']=$scalar("SELECT COUNT(*) FROM crm_customers WHERE organization_id=?",[$orgId]);$metrics['invoices']=$scalar("SELECT COUNT(*) FROM sales_invoices WHERE organization_id=?",[$orgId]);$metrics['deliveries']=$scalar("SELECT COUNT(*) FROM sales_deliveries WHERE organization_id=?",[$orgId]);$metrics['returns']=$scalar("SELECT COUNT(*) FROM sales_returns WHERE organization_id=?",[$orgId]);$metrics['refunds']=$scalar("SELECT COUNT(*) FROM sales_refunds WHERE organization_id=?",[$orgId]);$tablesOk=true;foreach(sales_step15_tables() as $t)if(!business_table_exists($pdo,$t)){$tablesOk=false;break;}$sourceReady=$scalar("SELECT COUNT(*) FROM data_sources WHERE organization_id=? AND source_code='CUSTOMER-SALES' AND is_active=1",[$orgId])===1;if(!$sourceReady){sales_step15_source($pdo,$orgId);$sourceReady=$scalar("SELECT COUNT(*) FROM data_sources WHERE organization_id=? AND source_code='CUSTOMER-SALES' AND is_active=1",[$orgId])===1;}
$badLinkCoverage=$scalar("SELECT COUNT(*) FROM product_sale_ledger sl LEFT JOIN sales_customer_links cl ON cl.organization_id=sl.organization_id AND cl.order_id=sl.order_id WHERE sl.organization_id=? AND cl.id IS NULL",[$orgId]);$badLedgerCoverage=$scalar("SELECT COUNT(*) FROM product_sale_ledger sl LEFT JOIN sales_fulfillment_ledger f ON f.organization_id=sl.organization_id AND f.order_id=sl.order_id WHERE sl.organization_id=? AND f.id IS NULL",[$orgId]);
$badActiveInvoice=$scalar("SELECT COUNT(*) FROM sales_invoices i JOIN orders o ON o.id=i.order_id AND o.organization_id=i.organization_id JOIN product_sale_ledger sl ON sl.order_id=i.order_id AND sl.organization_id=i.organization_id WHERE i.organization_id=? AND sl.sale_status='active' AND i.status='active' AND (ABS(i.gross_amount-o.gross_amount)>0.01 OR ABS(i.discount_amount-o.discount_amount)>0.01 OR ABS(i.net_amount-o.net_amount)>0.01 OR ABS(i.volume_points-o.volume_points)>0.0005 OR ABS(i.tax_amount)>0.01)",[$orgId]);
$badDeliveryQty=$scalar("SELECT COUNT(*) FROM product_order_items i LEFT JOIN (SELECT di.order_item_id,SUM(di.quantity_dispatched) qty FROM sales_delivery_items di JOIN sales_deliveries d ON d.id=di.delivery_id AND d.organization_id=di.organization_id WHERE di.organization_id=? AND d.status IN ('dispatched','delivered') GROUP BY di.order_item_id) x ON x.order_item_id=i.id WHERE i.organization_id=? AND COALESCE(x.qty,0)>i.quantity+0.0005",[$orgId,$orgId]);$badDeliveredDate=$scalar("SELECT COUNT(*) FROM sales_deliveries WHERE organization_id=? AND status='delivered' AND delivered_date IS NULL",[$orgId]);
$badReturnQty=$scalar("SELECT COUNT(*) FROM inventory_sale_allocations a LEFT JOIN (SELECT inventory_allocation_id,SUM(quantity_returned) qty FROM sales_return_items sri JOIN sales_returns sr ON sr.id=sri.sales_return_id AND sr.organization_id=sri.organization_id WHERE sri.organization_id=? AND sr.status='posted' GROUP BY inventory_allocation_id) x ON x.inventory_allocation_id=a.id WHERE a.organization_id=? AND COALESCE(x.qty,0)>a.quantity+0.0005",[$orgId,$orgId]);$badReturnTx=$scalar("SELECT COUNT(*) FROM sales_return_items ri JOIN inventory_sale_allocations a ON a.id=ri.inventory_allocation_id AND a.organization_id=ri.organization_id LEFT JOIN inventory_transactions t ON t.id=ri.inventory_transaction_id AND t.organization_id=ri.organization_id WHERE ri.organization_id=? AND (t.id IS NULL OR t.movement_type<>'customer_return' OR t.quantity_delta<=0 OR ABS(t.quantity_delta-ri.quantity_returned)>0.0005 OR t.batch_id<>a.batch_id OR t.product_id<>ri.product_id)",[$orgId]);$badReturnCredit=$scalar("SELECT COUNT(*) FROM sales_returns r LEFT JOIN (SELECT sales_return_id,SUM(credit_amount) credit_sum FROM sales_return_items WHERE organization_id=? GROUP BY sales_return_id) x ON x.sales_return_id=r.id WHERE r.organization_id=? AND r.status='posted' AND ABS(r.total_credit-COALESCE(x.credit_sum,0))>0.01",[$orgId,$orgId]);
$badRefundOverPay=$scalar("SELECT COUNT(*) FROM (SELECT sl.order_id,COALESCE(p.paid,0) paid,COALESCE(r.refunded,0) refunded FROM product_sale_ledger sl LEFT JOIN (SELECT order_id,SUM(amount) paid FROM product_sale_payments WHERE organization_id=? AND status='active' GROUP BY order_id) p ON p.order_id=sl.order_id LEFT JOIN (SELECT order_id,SUM(amount) refunded FROM sales_refunds WHERE organization_id=? AND status='active' GROUP BY order_id) r ON r.order_id=sl.order_id WHERE sl.organization_id=?) x WHERE x.refunded>x.paid+0.01",[$orgId,$orgId,$orgId]);$badReturnRefund=$scalar("SELECT COUNT(*) FROM sales_returns r LEFT JOIN (SELECT sales_return_id,SUM(amount) refunded FROM sales_refunds WHERE organization_id=? AND status='active' AND sales_return_id IS NOT NULL GROUP BY sales_return_id) x ON x.sales_return_id=r.id WHERE r.organization_id=? AND COALESCE(x.refunded,0)>r.total_credit+0.01",[$orgId,$orgId]);
$badLedgerMath=$scalar("SELECT COUNT(*) FROM sales_fulfillment_ledger f JOIN orders o ON o.id=f.order_id AND o.organization_id=f.organization_id LEFT JOIN (SELECT order_id,SUM(total_credit) ret FROM sales_returns WHERE organization_id=? AND status='posted' GROUP BY order_id) r ON r.order_id=f.order_id LEFT JOIN (SELECT order_id,SUM(amount) paid FROM product_sale_payments WHERE organization_id=? AND status='active' GROUP BY order_id) p ON p.order_id=f.order_id LEFT JOIN (SELECT order_id,SUM(amount) ref FROM sales_refunds WHERE organization_id=? AND status='active' GROUP BY order_id) x ON x.order_id=f.order_id WHERE f.organization_id=? AND (ABS(f.original_charge-o.net_amount)>0.01 OR ABS(f.return_credit-COALESCE(r.ret,0))>0.01 OR ABS(f.gross_collected-COALESCE(p.paid,0))>0.01 OR ABS(f.refund_amount-COALESCE(x.ref,0))>0.01 OR ABS(f.effective_charge-GREATEST(0,o.net_amount-COALESCE(r.ret,0)))>0.01 OR ABS(f.net_collected-GREATEST(0,COALESCE(p.paid,0)-COALESCE(x.ref,0)))>0.01 OR ABS(f.receivable_amount-GREATEST(0,GREATEST(0,o.net_amount-COALESCE(r.ret,0))-GREATEST(0,COALESCE(p.paid,0)-COALESCE(x.ref,0))))>0.01 OR ABS(f.customer_credit_due-GREATEST(0,GREATEST(0,COALESCE(p.paid,0)-COALESCE(x.ref,0))-GREATEST(0,o.net_amount-COALESCE(r.ret,0))))>0.01)",[$orgId,$orgId,$orgId,$orgId]);
$cancelledAfterSales=$scalar("SELECT COUNT(*) FROM product_sale_ledger sl WHERE sl.organization_id=? AND sl.sale_status='cancelled' AND (EXISTS(SELECT 1 FROM sales_returns r WHERE r.organization_id=sl.organization_id AND r.order_id=sl.order_id AND r.status='posted') OR EXISTS(SELECT 1 FROM sales_refunds rf WHERE rf.organization_id=sl.organization_id AND rf.order_id=sl.order_id AND rf.status='active') OR EXISTS(SELECT 1 FROM sales_deliveries d WHERE d.organization_id=sl.organization_id AND d.order_id=sl.order_id AND d.status='delivered'))",[$orgId]);
$badRaw=$scalar("SELECT COUNT(*) FROM (SELECT raw_source_id rid FROM sales_invoices WHERE organization_id=? AND raw_source_id IS NOT NULL UNION ALL SELECT raw_source_id FROM sales_deliveries WHERE organization_id=? AND raw_source_id IS NOT NULL UNION ALL SELECT raw_source_id FROM sales_returns WHERE organization_id=? AND raw_source_id IS NOT NULL UNION ALL SELECT raw_source_id FROM sales_refunds WHERE organization_id=? AND raw_source_id IS NOT NULL UNION ALL SELECT raw_source_id FROM crm_interactions WHERE organization_id=? AND raw_source_id IS NOT NULL) z LEFT JOIN raw_source_records rr ON rr.id=z.rid LEFT JOIN data_sources ds ON ds.id=rr.data_source_id WHERE rr.id IS NULL OR ds.source_code<>'CUSTOMER-SALES'",[$orgId,$orgId,$orgId,$orgId,$orgId]);$badReturnInventorySource=$scalar("SELECT COUNT(*) FROM sales_return_items sri JOIN inventory_transactions t ON t.id=sri.inventory_transaction_id AND t.organization_id=sri.organization_id LEFT JOIN raw_source_records rr ON rr.id=t.raw_source_id LEFT JOIN data_sources ds ON ds.id=rr.data_source_id WHERE sri.organization_id=? AND (rr.id IS NULL OR ds.source_code<>'INVENTORY')",[$orgId]);$badBatchBalance=$scalar("SELECT COUNT(*) FROM inventory_batches b LEFT JOIN (SELECT batch_id,SUM(CASE WHEN status='active' THEN quantity_delta ELSE 0 END) q FROM inventory_transactions WHERE organization_id=? GROUP BY batch_id) x ON x.batch_id=b.id WHERE b.organization_id=? AND ABS(b.current_quantity-COALESCE(x.q,0))>0.0005",[$orgId,$orgId]);
$requiredFiles=['customer_center.php','customer_detail.php','sales_fulfillment.php','sales_invoice.php','sales_delivery.php','sales_returns.php','sales_refunds.php','sales_receivables.php','crm_followups.php','sales_analytics_step15.php','sales_export_step15.php','config/sales_step15.php'];$filesOk=true;foreach($requiredFiles as $f)if(!is_file(__DIR__.'/'.$f)){$filesOk=false;break;}
s15add($checks,'Legacy workbook preserved',$metrics['legacy_total']===757&&$metrics['legacy_mapped']===757&&$metrics['legacy_pending']===0,$metrics['legacy_mapped'].' / 757 mapped • '.$metrics['legacy_pending'].' pending');s15add($checks,'STEP 11 catalog preserved',$metrics['products']===64,$metrics['products'].' / 64 active products');s15add($checks,'STEP 15 CRM / fulfillment tables',$tablesOk,count(sales_step15_tables()).' required tables');s15add($checks,'CUSTOMER-SALES source trace',$sourceReady,'Dedicated CUSTOMER-SALES raw source');s15add($checks,'Every Product Sale has customer snapshot link',$badLinkCoverage===0,$metrics['sales'].' sales • '.$badLinkCoverage.' missing link(s)');s15add($checks,'Every Product Sale has fulfillment ledger',$badLedgerCoverage===0,$badLedgerCoverage.' missing ledger(s)');s15add($checks,'Active invoice preserves original sale',$badActiveInvoice===0,$metrics['invoices'].' invoices • '.$badActiveInvoice.' immutable snapshot issue(s)');s15add($checks,'Dispatch quantity never exceeds sold quantity',$badDeliveryQty===0,$badDeliveryQty.' over-dispatch issue(s)');s15add($checks,'Delivered records have delivered date',$badDeliveredDate===0,$badDeliveredDate.' delivered-date issue(s)');s15add($checks,'Customer return never exceeds sold allocation',$badReturnQty===0,$badReturnQty.' over-return issue(s)');s15add($checks,'Customer return restores original batch',$badReturnTx===0,$badReturnTx.' return inventory issue(s)');s15add($checks,'Return credit notes reconcile',$badReturnCredit===0,$badReturnCredit.' return credit issue(s)');s15add($checks,'Refund never exceeds active customer payment',$badRefundOverPay===0,$badRefundOverPay.' over-refund sale(s)');s15add($checks,'Return-linked refund stays within credit note',$badReturnRefund===0,$badReturnRefund.' return refund issue(s)');s15add($checks,'Receivable ledger math reconciles',$badLedgerMath===0,$badLedgerMath.' financial ledger issue(s)');s15add($checks,'Cancelled sale after-sales safety',