}catch(Throwable $e){$error=$e->getMessage();}$passed=count(array_filter($checks,static fn($c)=>$c['ok']));$failed=count($checks)-$passed;$complete=$error===null&&$failed===0;function s15_h(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
