lass="os-status-row"><span class="os-chip <?= $complete?'good':'' ?>"><?= $complete?'STEP 15 COMPLETE':'Review required' ?></span><span class="os-chip good"><?= number_format($metrics['legacy_mapped']??0) ?> / 757 legacy</span><span class="os-chip"><?= number_format($metrics['sales']??0) ?> product sales</span><span class="os-chip"><?= number_format($metrics['customers']??0) ?> customers</span><span class="os-chip"><?= number_format($metrics['invoices']??0) ?> invoices</span></div></section><?php if($error):?><div class="pp-alert bad"><strong>Audit diagnostic:</strong> <?= s15_h($error) ?></div><?php endif;?><section class="os-card" style="margin-top:14px"><div class="os-title-row"><div><h2>Completion Checks</h2><p>No fake customer, invoice, delivery, return or refund is required. Zero real sales activity is a valid starting state.</p></div><span class="pp-badge <?= $complete?'':'warn' ?>"><?= $passed ?> PASS / <?= $failed ?> REVIEW</span></div><div class="pp-audit-grid"><?php foreach($checks as $c):?><div class="pp-audit"><div><b><?= s15_h($c['name']) ?></b><span><?= s15_h($c['detail']) ?></span></div><strong class="<?= $c['ok']?'':'bad' ?>"><?= $c['ok']?'PASS':'REVIEW' ?></strong></div><?php endforeach;?></div></section><div class="os-footer-note"><strong>STEP 15 completion rule:</strong> Customer, Invoice, Delivery, Return/Credit, Refund and Receivable remain separate traceable facts.</div></main></div><script src="assets/business-collapsible.js?v=20260820-1" defer></script></body></html>
